from itertools import permutations

singers = ["Kammer", "Lugo", "Trillo", "Waite", "Yoshida", "Zinn"]
recorded = {"Kammer", "Lugo"}

def valid(order):
    # order: tuple of names, index 0 = audition 1
    pos = {n: i + 1 for i, n in enumerate(order)}
    if order[3] in recorded:
        return False
    if order[4] not in recorded:
        return False
    if not (pos["Waite"] < pos["Kammer"] and pos["Waite"] < pos["Lugo"]):
        return False
    if not pos["Kammer"] < pos["Trillo"]:
        return False
    if not pos["Zinn"] < pos["Yoshida"]:
        return False
    return True

sols = [p for p in permutations(singers) if valid(p)]
# extra condition: Kammer immediately before Yoshida
cond = [p for p in sols if p.index("Yoshida") == p.index("Kammer") + 1]

print("total valid orders:", len(sols))
print("orders with Kammer immediately before Yoshida:", len(cond))
for p in cond:
    print(p)

options = {
    "A": lambda p: p.index("Kammer") + 1 == 2,
    "B": lambda p: p.index("Trillo") + 1 == 4,
    "C": lambda p: p.index("Waite") + 1 == 3,
    "D": lambda p: p.index("Yoshida") + 1 == 6,
    "E": lambda p: p.index("Zinn") + 1 == 2,
}

could = {}
for k, f in options.items():
    wit = [p for p in cond if f(p)]
    could[k] = bool(wit)
    print(k, "could be true:", could[k], "witnesses:", len(wit))

correct = [k for k, v in could.items() if v]
print("Options that could be true:", correct)
submitted = "A"
if correct == [submitted]:
    print("CHECK PASS")
else:
    print("CHECK FAIL: submitted", submitted, "expected", correct)
